package it.evadid.workbook.elements.interactionElements.programming.state.snap

import it.evadid.vm.conversion.snapmodelxml.SnapModelToXml.toXml
import it.evadid.vm.conversion.snapxmlmodel.SnapScalaXmlCodec

/** Pen trails and thumbnails are generated by the Snap runtime and do not belong to an answer. */
object SnapGeneratedImages {
  /** The XML without generated images, otherwise unchanged; text that is not Snap XML stays as it is. */
  def remove(xml: String): String =
    SnapScalaXmlCodec.parse(xml).fold(_ => xml, document => document.withoutGeneratedImages.toXml)
}
